"""Bilingual, factual phone feature copy; no owner link or pairing secret."""
import html
PUBLIC='https://aionpc.ru:8445/'
from showcase_content import availability
PREVIEW={lang:availability(lang) for lang in ['ru','en']}

def section(lang):
 en=lang=='en';path=('/en' if en else '')+'/guides/phone-access/'
 title='Your agent.<br>In your pocket.' if en else 'Ваш агент.<br>Всегда под рукой.'
 lead='Leave Freedom GPT running on your computer. Open the same chats on your iPhone, watch progress and send the next task.' if en else 'Оставьте Freedom GPT работать на компьютере. Откройте те же чаты на iPhone, следите за результатом и отправляйте новые задания.'
 lead+='<small class="phone-preview">'+html.escape(PREVIEW[lang])+'</small>'
 points=['Optional, free phone access','QR code and approval on your PC','Revoke access whenever you need'] if en else ['По желанию, без дополнительной подписки','QR-код и подтверждение на вашем ПК','Доступ можно отозвать в любой момент']
 items=''.join('<li><span>✓</span>'+html.escape(x)+'</li>' for x in points)
 return f'''<section class="section wrap phone-feature" id="phone"><div class="phone-feature-copy"><div class="eyebrow">FREEDOM GPT / PHONE ACCESS</div><h2>{title}</h2><p>{lead}</p><ul>{items}</ul><div class="phone-feature-links"><a class="button secondary" href="{path}">{'Connect my phone' if en else 'Как подключить телефон'} ↗</a><a class="text-link" href="{PUBLIC}">{'Open phone access' if en else 'Открыть пульт'} ↗</a></div><small>{'Available in version 1.6.0+. Your PC must stay awake and online. No VPN profile or App Store app required. Phone traffic passes through the project relay; chat history and files are not stored there. The free relay has capacity and transfer limits.' if en else 'Доступно с версии 1.6.0. ПК должен быть включён, без сна и с интернетом. Профиль VPN и приложение из App Store не нужны. Данные проходят через сервер связи проекта; история и файлы на нём не сохраняются. У бесплатного сервиса есть ограничения нагрузки и передачи файлов.'}</small></div><figure class="phone-feature-device"><div class="phone-feature-camera" aria-hidden="true"></div><img src="/media/screenshots/phone-access.png" alt="{'Freedom GPT interface in a mobile browser' if en else 'Интерфейс Freedom GPT в мобильном браузере'}" width="390" height="844" loading="lazy"><figcaption>{'Your computer does the work. Your phone keeps you in touch.' if en else 'Компьютер выполняет задачи. Телефон держит вас в курсе.'}</figcaption></figure></section>'''

def guide(lang):
 en=lang=='en'
 steps=[('Open the app on your computer','Install Freedom GPT 1.6.0 or newer. Open Settings → Phone access. Local AI works as before; phone access is optional.'),
        ('Enable the connection','Turn on Phone access. The app makes an outbound HTTPS/WebSocket connection to the project relay. You do not need to open a router port or provide SSH credentials.'),
        ('Scan the QR code','Click Show QR code on the computer and scan it with your iPhone camera. In Safari, tap Connect this phone. The QR code lasts five minutes and can be claimed once.'),
        ('Approve on your computer','Compare the six-digit codes on both screens. Click Approve on the PC only if this is your phone. Scanning the QR code alone does not grant access.'),
        ('Open your chats','The mobile page opens the same PC and chat history. Watch progress, send tasks, edit the queue or steer work. The agent keeps the permissions selected in the desktop app.'),
        ('Keep it one tap away','In Safari, choose Share → Add to Home Screen. Keep Freedom GPT running on an awake, internet-connected computer. Closing Safari does not stop work on the PC.')] if en else [
        ('Откройте приложение на компьютере','Установите Freedom GPT 1.6.0 или новее. Откройте Настройки → Доступ с телефона. Функция включается по желанию.'),
        ('Включите соединение','Включите переключатель «Доступ с телефона». Программа сама подключится к серверу связи проекта по HTTPS/WebSocket. Настраивать роутер, открывать порт на домашнем ПК или вводить SSH-пароль не нужно.'),
        ('Отсканируйте QR-код','На ПК нажмите «Показать QR-код». Отсканируйте его камерой iPhone, откройте Safari и нажмите «Подключить этот телефон». QR-код действует пять минут и принимается один раз.'),
        ('Подтвердите телефон на ПК','Сравните шестизначные коды на обоих экранах. Нажмите «Разрешить» на компьютере, только если это ваш телефон. Одного QR-кода для доступа недостаточно.'),
        ('Откройте свои чаты','Телефон показывает тот же компьютер и переписку. Можно следить за работой, отправлять задания, редактировать очередь и вносить поправки. Права агента остаются такими, какие вы выбрали в программе.'),
        ('Сохраните быстрый вход','В Safari выберите Поделиться → На экран «Домой». Оставляйте Freedom GPT запущенным на ПК: нужны интернет и отключённый сон. Закрытие Safari не останавливает задачи на компьютере.')]
 parts=['<section class="guide-phone-preview"><h2>'+('Windows preview' if en else 'Проверяем Windows-версию')+'</h2><p>'+html.escape(PREVIEW[lang])+'</p></section><section><h2>'+('Connect in a few steps' if en else 'Подключение за несколько шагов')+'</h2><ol>']
 for title,body in steps:parts.append('<li><h3>'+html.escape(title)+'</h3><p>'+html.escape(body)+'</p></li>')
 parts.append('</ol></section>')
 topics=[('How access is protected','Each installation creates its own PC key. A phone is authorized only after explicit approval on that PC. Its browser session is stored in a Secure, HttpOnly, SameSite=Strict cookie. One phone session is active per PC. Approving a replacement revokes the previous one.'),
 ('Where data goes','Models, computation and saved project history stay on the PC. During remote access, requests, replies and files pass through the project relay over HTTPS. The relay does not persist chat content or files, but it handles the transferred data. This is not a claim of end-to-end encryption. Enable the feature only if you trust the chosen relay operator.'),
 ('Turn it off or revoke the phone','On the PC, open Settings → Phone access. Revoke access invalidates the phone session and closes its live connection. Turning the switch off disconnects the PC from the relay while local work continues.'),
 ('Requirements and limits','Internet is required on both devices. Your computer must stay awake with Freedom GPT running. The free project relay initially allows up to 25 connected PCs; it may reject new connections when full. Phone uploads are limited to 20 MB per request and streamed downloads to 512 MB. Large model downloads should run on the computer, not through the phone relay. API model charges, if selected, remain subject to the provider’s terms.'),
 ('If the page stops loading','Check the PC is awake and the app is running. Refresh Safari after switching Wi-Fi/mobile networks. The phone remains authorized when the PC reconnects. Clearing cookies or using a private browsing session may require pairing again. On restrictive mobile networks the relay’s HTTPS port may be blocked; the local application remains available.'),
 ('What was checked','Two independent PC clients were tested in an isolated fixture for isolation, mandatory PC approval, one-time QR codes, expiry, file streaming, live WebSocket updates, reconnection and revocation. The Windows installer was checked in a separate local installation. A mobile browser layout was tested. This does not replace testing on physical iPhones, Macs or every mobile network.')] if en else [
 ('Как защищён доступ','Каждая установка создаёт собственный ключ компьютера. Телефон получает доступ только после подтверждения на этом ПК. Разрешение хранится в cookie браузера с Secure, HttpOnly и SameSite=Strict. Для ПК действует один сеанс телефона: подтверждение нового заменяет прежний.'),
 ('Где проходят данные','Модели, вычисления и сохранённая история проектов остаются на ПК. При удалённой работе запросы, ответы и файлы проходят через сервер связи проекта по HTTPS. Он не сохраняет содержимое чатов и файлов, но обрабатывает передаваемые данные. Сквозное шифрование здесь не заявляется. Включайте функцию, если доверяете оператору выбранного сервера.'),
 ('Как выключить доступ','На компьютере откройте Настройки → Доступ с телефона. «Отозвать доступ» отменяет разрешение телефона и закрывает его активное соединение. Выключение переключателя отключает ПК от сервера связи; локальная работа продолжается.'),
 ('Требования и ограничения','На обоих устройствах нужен интернет. ПК должен быть включён, без сна и с запущенным Freedom GPT. Бесплатный сервер проекта на старте допускает до 25 подключённых ПК; при заполнении предложит повторить подключение позже. Загрузка с телефона ограничена 20 МБ на запрос, потоковое скачивание — 512 МБ. Большие модели скачивайте на самом компьютере. Если вы выбрали платную API-модель, действуют тарифы её провайдера.'),
 ('Если страница не открывается','Проверьте, что компьютер не спит и программа работает. Обновите Safari после смены Wi-Fi или мобильной сети. После возвращения ПК в сеть разрешённый телефон подключается снова. Очистка cookie и режим инкогнито могут потребовать нового QR-кода. Некоторые сети могут блокировать HTTPS-порт сервиса; локальная работа программы при этом доступна.'),
 ('Что проверено','В изолированных тестах с двумя независимыми установками проверены изоляция, обязательное подтверждение на компьютере, одноразовый QR-код, срок его действия, передача файлов, живые обновления, переподключение и отзыв доступа. Windows-установщик проверен в отдельной локальной установке. Проверена мобильная вёрстка. Это не заменяет испытание на реальных iPhone, Mac и всех мобильных сетях.')]
 for title,body in topics:parts.append('<section><h2>'+html.escape(title)+'</h2><p>'+html.escape(body)+'</p></section>')
 parts.append('<p><a class="button secondary" href="'+PUBLIC+'">'+('Open the phone portal' if en else 'Открыть пульт на телефоне')+' ↗</a></p>')
 return ''.join(parts)
